const katex=require('katex');
const math=latex=>'<div class="nexus-math-block"><div class="math-preview">'+katex.renderToString(latex,{displayMode:true,throwOnError:false})+'</div><div class="nexus-math-card" style="display:none"><button>Math editor</button></div></div>';
const image='<img alt="Synthetic image" width="600" height="180" style="max-width:100%;height:auto" src="data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="600" height="180"><rect width="600" height="180" fill="lightblue"/><text x="20" y="80">SYNTHETIC IMAGE</text></svg>')+'">';
const table=(rows,head='<tr data-header="true"><th colspan="2">TABLE HEADER</th></tr>')=>'<table style="width:100%;table-layout:fixed;border-collapse:collapse"><thead>'+head+'</thead><tbody>'+rows+'</tbody></table>';
const row=(i,content='Body')=>'<tr data-rowid="r'+i+'"><td style="border:1px solid #555;padding:7px">ROW_'+String(i).padStart(3,'0')+'</td><td style="border:1px solid #555;padding:7px">'+content+'</td></tr>';
const cases={
 longTable:table(Array.from({length:125},(_,i)=>row(i,'中文 English content '+i)).join('')),
 merged:table('<tr data-rowid="merge0"><td rowspan="3">SPAN_ANCHOR</td><td>MERGE_0</td></tr><tr data-rowid="merge1"><td>'+image+'MERGE_1</td></tr><tr data-rowid="merge2"><td>'+math('x^2+\\frac{1}{2}')+'MERGE_2</td></tr>'+Array.from({length:45},(_,i)=>row(i,'Merged continuation')).join('')+'<tr data-rowid="tall"><td colspan="2"><p style="height:1300px">OVERSIZED_CELL</p></td></tr>'),
 columns:'<div data-type="multiColumn" data-ratio="38" style="display:grid;grid-template-columns:38fr 62fr;gap:16px"><div data-type="column">'+Array.from({length:70},(_,i)=>'<p style="margin:12px 0;min-height:40px">LEFT_'+String(i).padStart(3,'0')+' 中文長篇左欄 English text。</p>').join('')+'</div><div data-type="column">'+Array.from({length:15},(_,i)=>'<p style="margin:12px 0;min-height:40px">RIGHT_'+String(i).padStart(3,'0')+' 右欄。</p>').join('')+'</div></div>',
 mixed:'<details open><summary>Fold source</summary><div><p>FOLD_BEGIN</p>'+image+'<details open><summary>Nested</summary><p>NESTED_CONTENT</p></details></div></details>'+Array.from({length:25},(_,i)=>'<p>PARA_'+String(i).padStart(3,'0')+' '+('長篇中文 English 混排。'.repeat(15))+'</p>').join('')+math('\\underbrace{'+Array.from({length:35},(_,i)=>'x_{'+i+'}').join('+')+'}_{long\\ formula}')+'<pre style="white-space:pre;overflow:auto">CODE_BEGIN\n    '+('const wide = value; '.repeat(80))+'\nCODE_END</pre><div data-type="page-break" class="nexus-page-break"></div><p>AFTER_MANUAL_BREAK</p>'
};
function tokens(html){return [...html.matchAll(/(?:ROW|MERGE|LEFT|RIGHT|PARA)_\d{1,3}|SPAN_ANCHOR|OVERSIZED_CELL|FOLD_BEGIN|NESTED_CONTENT|CODE_BEGIN|CODE_END|AFTER_MANUAL_BREAK/g)].map(m=>m[0]);}
module.exports={cases,math,image,table,row,tokens};
